import{_ as n,o as i,c as t,a2 as a}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"Ratenbegrenzung","description":"","frontmatter":{},"headers":[],"relativePath":"de/advanced/ratelimit.md","filePath":"de/advanced/ratelimit.md","lastUpdated":1784903584000}'),s={name:"de/advanced/ratelimit.md"};function r(l,e,d,h,o,u){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="ratenbegrenzung" tabindex="-1">Ratenbegrenzung <a class="header-anchor" href="#ratenbegrenzung" aria-label="Permalink to &quot;Ratenbegrenzung&quot;">​</a></h1><h2 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h2><p>swag2mcp verfügt über einen integrierten Ratenbegrenzer, der verhindert, dass der LLM denselben API-Endpunkt zu häufig aufruft. Dies schützt vor versehentlichen doppelten Aufrufen und respektiert API-Ratenlimits.</p><h2 id="wie-es-funktioniert" tabindex="-1">Wie es funktioniert <a class="header-anchor" href="#wie-es-funktioniert" aria-label="Permalink to &quot;Wie es funktioniert&quot;">​</a></h2><p>Jeder Endpunkt hat eine Abklingzeit. Wenn der LLM versucht, denselben Endpunkt innerhalb der Abklingzeit erneut aufzurufen, wird der Aufruf mit einem strukturierten Fehler abgelehnt.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>t=0s  → invoke(endpoint) → wird ausgeführt</span></span>
<span class="line"><span>t=2s  → invoke(endpoint) → mit rate_limit-Fehler abgelehnt</span></span>
<span class="line"><span>t=12s → invoke(endpoint) → wird ausgeführt (Abklingzeit abgelaufen)</span></span></code></pre></div><h3 id="standardverhalten" tabindex="-1">Standardverhalten <a class="header-anchor" href="#standardverhalten" aria-label="Permalink to &quot;Standardverhalten&quot;">​</a></h3><ul><li><strong>Abklingzeit:</strong> 10 Sekunden pro Endpunkt</li><li><strong>Gültigkeitsbereich:</strong> Pro Endpunkt — der Aufruf von Endpunkt A hat keine Auswirkung auf Endpunkt B</li><li><strong>Fehlerantwort:</strong> Der LLM erhält einen <code>LLMError</code> mit dem Code <code>rate_limit</code> und einer Nachricht, die angibt, wie lange gewartet werden muss</li><li><strong>Zurücksetzen:</strong> Nach 10 Sekunden Inaktivität auf diesem Endpunkt</li></ul><h3 id="fehlerformat" tabindex="-1">Fehlerformat <a class="header-anchor" href="#fehlerformat" aria-label="Permalink to &quot;Fehlerformat&quot;">​</a></h3><p>Bei Ratenbegrenzung erhält der LLM:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate_limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ratenlimit für Endpunkt </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">abc123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> überschritten: versuchen Sie es in 8 Sekunden erneut&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Warten Sie, bis die Abklingzeit abgelaufen ist, und versuchen Sie dann, den Endpunkt erneut aufzurufen. Verwenden Sie das Suchtool, um andere Endpunkte zu finden, die Sie in der Zwischenzeit aufrufen können.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Der LLM kann diese Informationen nutzen, um zu warten und es erneut zu versuchen oder zu einem anderen Endpunkt zu wechseln.</p><h3 id="warum-es-existiert" tabindex="-1">Warum es existiert <a class="header-anchor" href="#warum-es-existiert" aria-label="Permalink to &quot;Warum es existiert&quot;">​</a></h3><ul><li><strong>Verhindert versehentliche doppelte Aufrufe</strong> — der LLM könnte denselben Endpunkt mehrmals schnell hintereinander aufrufen</li><li><strong>Schützt vor API-Ratenlimits</strong> — viele APIs haben eigene Ratenlimits, deren Überschreitung zu Fehlern führen würde</li><li><strong>Spart Ressourcen</strong> — reduziert unnötigen Netzwerkverkehr</li></ul><h2 id="konfiguration" tabindex="-1">Konfiguration <a class="header-anchor" href="#konfiguration" aria-label="Permalink to &quot;Konfiguration&quot;">​</a></h2><p>Sie können den Ratenbegrenzer deaktivieren oder das Abklingintervall ändern:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ratenbegrenzer vollständig deaktivieren</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_ratelimiter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Benutzerdefiniertes Abklingintervall</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rate_limit_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30s</span></span></code></pre></div><h3 id="disable-ratelimiter" tabindex="-1">disable_ratelimiter <a class="header-anchor" href="#disable-ratelimiter" aria-label="Permalink to &quot;disable_ratelimiter&quot;">​</a></h3><ul><li><strong>Typ:</strong> <code>bool</code></li><li><strong>Standard:</strong> <code>false</code></li><li><strong>Wirkung:</strong> Wenn <code>true</code>, wird der Pro-Endpunkt-Ratenbegrenzer deaktiviert. Der LLM kann denselben Endpunkt wiederholt ohne Wartezeit aufrufen.</li><li><strong>Wann aktivieren:</strong> Testen, Debuggen oder wenn Sie denselben Endpunkt mehrmals schnell hintereinander aufrufen müssen.</li><li><strong>Wann deaktiviert lassen (empfohlen):</strong> Produktion. Der Ratenbegrenzer verhindert versehentlichen Missbrauch.</li></ul><h3 id="rate-limit-interval" tabindex="-1">rate_limit_interval <a class="header-anchor" href="#rate-limit-interval" aria-label="Permalink to &quot;rate_limit_interval&quot;">​</a></h3><ul><li><strong>Typ:</strong> Dauer (Go-Format: <code>10s</code>, <code>30s</code>, <code>1m</code>)</li><li><strong>Standard:</strong> <code>10s</code></li><li><strong>Wirkung:</strong> Legt die Abklingzeit zwischen Aufrufen desselben Endpunkts fest.</li><li><strong>Wann erhöhen:</strong> APIs mit strengen Ratenlimits (z. B. 10 Anfragen pro Minute).</li><li><strong>Wann verringern:</strong> Interne APIs, bei denen Sie die Last kontrollieren.</li><li><strong>Beispiele:</strong> <code>5s</code>, <code>30s</code>, <code>1m</code>, <code>2m</code></li></ul><h2 id="wichtige-hinweise" tabindex="-1">Wichtige Hinweise <a class="header-anchor" href="#wichtige-hinweise" aria-label="Permalink to &quot;Wichtige Hinweise&quot;">​</a></h2><ul><li><strong>Pro-Endpunkt-Verfolgung</strong> — jeder Endpunkt wird unabhängig verfolgt. Der Aufruf eines Endpunkts hat keine Auswirkung auf andere.</li><li><strong>Fehler wird an LLM zurückgegeben</strong> — der zweite Aufruf innerhalb der Abklingzeit wird mit einem <code>rate_limit</code>-Fehler abgelehnt. Der LLM erhält die Abklingdauer und kann nach dem Warten erneut versuchen.</li><li><strong>Keine Bereinigung erforderlich</strong> — der Ratenbegrenzer verfolgt Endpunkte automatisch und erfordert keine Wartung.</li></ul>`,23)])])}const g=n(s,[["render",r]]);export{k as __pageData,g as default};
